// 1. 获取所有输入条目 (Items)
const items = $input.all();

// 2. 遍历并规范化每一个条目
return items.map(item => {
  // 兼容 Webhook (body) 和 直接传参
  const data = item.json.body || item.json;

  // --- 逻辑 A: 规范化 URL 列表 (防御性编程) ---
  let rawUrls = data.target_urls || data.target_url || [];
  if (typeof rawUrls === 'string') {
    rawUrls = rawUrls.split(',').map(u => u.trim()).filter(Boolean);
  } else if (!Array.isArray(rawUrls)) {
    rawUrls = [];
  }
  const target_urls = [...new Set(rawUrls.filter(url => typeof url === 'string' && url.trim() !== ''))];

  // --- 逻辑 B: 规范化撰稿指南 ---
  const triage_prompt = data.focus_instruction || data.triage_prompt || "请提取核心价值，输出结构化的 Markdown 研报。";

  // --- 逻辑 C: 动态推断目标数量 ---
  let target_count = data.target_count;
  if (!target_count) {
    target_count = target_urls.length > 0 ? target_urls.length : 3;
  }

  // 返回规范化后的 Item 结构
  return {
    json: {
      content_id: data.content_id || `ID_${Math.random().toString(36).substr(2, 9)}`, // 容错：无 ID 时生成临时 ID
      topic_intent: data.topic_intent || "",
      source_lane: data.source_lane || "auto",
      timeframe: data.timeframe || "any",
      target_count: target_count,
      triage_prompt: triage_prompt,
      target_urls: target_urls,
      target_url: target_urls.join(", ") // 保持向下兼容
    }
  };
});

