parameters.jsCode:
// 1. 获取 Router 吐出的 Agent 任务清单
const items = $input.all();

// 2. 【防弹设计】尝试跨节点获取原始数据。如果找不到节点，安全降级为空数组
let originalInputs =[];
try {
  originalInputs = $('Normalize Inputs').all().map(i => i.json);
} catch (e) {
  console.log("[Gateway Warning] 无法跨节点读取 Normalize Inputs，将使用默认安全值。");
}

// 3. 遍历、缝合并扁平化
const flattenedItems = items.flatMap(item => {
  const data = item.json.output || item.json;
  const content_id = data.content_id || "MISSING_ID";

  // 核心缝合逻辑：通过 content_id 找到当初传进来的那个原始请求
  const originalData = originalInputs.find(orig => orig.content_id === content_id) || {};

  // 🌟 无论大模型怎么想，target_count 永远使用用户最初设定的真实值！(找不到则默认为 1)
  const true_target_count = originalData.target_count || 1;
  const mode = data.mode || "research";
  const tasks = data.tasks ||[];

  // 将拆解的子任务实例化为独立 n8n Item，并注入真实的 target_count
  return tasks.map(t => ({
    json: {
      content_id: content_id,
      mode: mode,
      target_count: true_target_count, // 彻底锁死，不再受任务数组长度影响！
      target: t.target || "google",
      query: t.query || "",
      target_url: t.target_url || ""
    }
  }));
});

return flattenedItems;

// 1. 继承上游所有元数据 (防止 Context Amnesia)
const item = $input.item.json;

// 2. 获取全局上下文 (从最源头提取撰稿指南)
let triage_prompt = "";
try {
  triage_prompt = $('Normalize Inputs').first().json.triage_prompt || "";
} catch(e) {}

// 3. 动态组装给 MCP 浏览器的 Prompt
let objective = "请你作为 AI 物理浏览器领航员，前往此页面提取核心正文，并输出为纯净的标准 Markdown。\n";

if (item.query) {
  objective += `【提取重点关注实体/关键词】: ${item.query}\n`;
}
if (triage_prompt) {
  objective += `【最终研报目标参考】: ${triage_prompt}\n`;
}
objective += "【注意】: 请忽略底部的广告、评论区无关争吵和点赞引导。";

// 4. 返回完整结构 (解构合并)
return {
  json: {
    ...item, // 👈 核心：保留 content_id, mode, target_count 等所有字段！
    objective: objective,
    start_url: item.target_url || ""
  }
};

// 1. 提取当前失败的原子任务
const item = $input.item.json;
const failedUrl = item.target_url || item.url || "未知URL";

// 2. 尝试获取全局指南
let triage_prompt = "";
try {
  triage_prompt = $('Normalize Inputs').first().json.triage_prompt || "";
} catch(e) {}

// 3. 组装最高级别的接管指令
let objective = `【系统降级警报】Firecrawl 云端爬虫遭遇反爬拦截 (403) 或死链。请你作为最后的底牌，启动物理浏览器前往此页面提取正文，输出标准 Markdown。\n`;
if (item.query) {
  objective += `【提取重点】: ${item.query}\n`;
}
if (triage_prompt) {
  objective += `【研报目标】: ${triage_prompt}\n`;
}

// 4. 完美变身为 MCP 引擎需要的 Payload 格式
return {
  json: {
    ...item, // 核心：带着 content_id 去抢救！
    objective: objective,
    start_url: failedUrl
  }
};

// 1. 继承上游的全部上下文（极其重要！绝不能把 content_id 和 final_narrative 弄丢）
const item = $input.item.json;

// 2. 提取定向搜证的查询词
// 在 Research 分支中，极具杀伤力的搜索指令存在于 topic_intent 里
// 如果为空，兜底使用标题
const finalQuery = item.topic_intent || item.query || item.title || "Latest tech news";

// 3. 时间清洗与双规格式化 (同时兼容 Tavily 和 Brave)
const timeframe = item.timeframe || 'any';
let tavilyTimeRange = undefined;
let braveFreshness = undefined;

if (timeframe !== 'any') {
  const match = timeframe.match(/(\d+)([hd])/);
  if (match) {
    const hours = match[2] === 'd' ? parseInt(match[1]) * 24 : parseInt(match[1]);

    if (hours <= 24) { 
      tavilyTimeRange = "day"; 
      braveFreshness = "pd"; // Brave 的 past day
    } else if (hours <= 168) { 
      tavilyTimeRange = "week"; 
      braveFreshness = "pw"; // Brave 的 past week
    } else if (hours <= 720) { 
      tavilyTimeRange = "month"; 
      braveFreshness = "pm"; // Brave 的 past month
    } else { 
      tavilyTimeRange = "year"; 
      braveFreshness = "py"; // Brave 的 past year
    }
  }
}

// 4. 组装 Tavily API 专属请求体 (用于 Tavily A 和 Tavily B)
const tavilyPayload = {
  // 注意：不要把 API Key 硬编码在代码里，让 HTTP 节点去使用 Credentials，这里只传参数
  "query": finalQuery,
  "search_depth": "advanced", // 定向搜证必须用 advanced，挖得更深
  "include_answer": true,
  "include_raw_content": false,
  "max_results": 5
};
if (tavilyTimeRange) tavilyPayload.time_range = tavilyTimeRange;

// 5. 组装 Brave API 专属 Query Parameters (用于最后的兜底)
const braveQs = {
  "q": finalQuery,
  "count": 5
};
if (braveFreshness) braveQs.freshness = braveFreshness;

// 6. 将组装好的炸药包挂载在 item 上，继续向下流转
return {
  json: {
    ...item, 
    tavily_payload: tavilyPayload,
    brave_qs: braveQs
  }
};

// 1. 提取原始任务数据 (重要：包含 content_id)
const item = $input.item.json;

// 2. 安全提取 Tavily 结果 (如果是报错流入的，结果为空)
const results = item.results ||[];
const aiAnswer = item.answer || "";

// 3. 映射为全域标准情报格式
let intel = results.map(res => ({
  source: "Tavily Search",
  title: res.title || "未知标题",
  url: res.url || "",
  snippet: res.content || ""
}));

// 4. 追加 Tavily 的 AI 原生总结 (高权重)
if (aiAnswer) {
  intel.unshift({
    source: "Tavily AI Summary",
    title: "Tavily 智能综述: " + (item.tavily_payload?.query || "Search Result"),
    url: "https://tavily.com",
    snippet: aiAnswer
  });
}

// 5. 如果抓取完全失败/无结果，依然返回一条空情报，保证下游闭环
if (intel.length === 0) {
  intel.push({
    source: "Tavily Search (Failed)",
    title: "无有效搜索结果",
    url: "",
    snippet: "未能检索到相关情报。"
  });
}

// 6. 清理临时变量，保留必要数据输出给 Fan-in 节点
delete item.tavily_payload;
delete item.results;
delete item.answer;
delete item.images;

return {
  json: {
    ...item,        // 👈 核心：身份证 (content_id) 完美保留
    intel: intel   // 存放标准化后的短情报数组
  }
};

// 1. 获取 Loop 节点 (Done 分支) 抓取回来的所有碎片数据
const items = $input.all();
console.log(`[Fan-in] 收到待聚合的碎片条目数: ${items.length}`);

// 2. 【核心简化】直接从大门节点获取全局唯一契约！
// 因为母工作流是 Run once for each item，所以这里绝对安全且唯一
const globalInput = $('Normalize Inputs').first().json;
const content_id = globalInput.content_id || "MISSING_ID";
const triage_prompt = globalInput.triage_prompt || "请输出结构化的 Markdown 研报。";
const topic_intent = globalInput.topic_intent || "";
const target_count = globalInput.target_count || 1;

// 3. 初始化唯一的情报池
const allIntel =[];
const seenUrls = new Set();

// 内部辅助函数：处理并推入情报，包含 Token 软截断保护
const addIntel = (candidate) => {
  if (!candidate.title && !candidate.intel_content && !candidate.snippet) return;

  const rawUrl = candidate.url || candidate.link || "";
  const normalizedUrl = rawUrl.toLowerCase().replace(/\/$/, "");
  if (normalizedUrl && seenUrls.has(normalizedUrl)) return;

  // 防 Token 溢出截断 (80,000 字符)
  if (candidate.intel_content && candidate.intel_content.length > 80000) {
      candidate.intel_content = candidate.intel_content.substring(0, 80000) + "\n\n...[网关警告：由于长度超限，后文已被截断]...";
  }

  // 标记来源
  if (!candidate.source) {
      if (rawUrl.includes("zhihu")) candidate.source = "Zhihu";
      else if (rawUrl.includes("tavily")) candidate.source = "Tavily";
      else candidate.source = "Deep Scrape Engine";
  }

  if (normalizedUrl) seenUrls.add(normalizedUrl);
  allIntel.push(candidate);
};

// 4. 遍历提取所有抓取结果
for (const item of items) {
  const json = item.json;

  // 情况 A: MCP / Firecrawl 返回的长文本
  if (json.output || json.result || json.markdown) {
    const rawContent = json.output || json.result || json.markdown;
    let extractedTitle = "深度抓取长文 (MCP/Firecrawl)";
    const titleMatch = rawContent.match(/^#\s+(.+)$/m);
    if (titleMatch) extractedTitle = titleMatch[1];

    addIntel({
      source: "Deep Scrape Engine",
      title: extractedTitle,
      url: json.target_url || json.url,
      intel_content: rawContent
    });
  }
  // 情况 B: 标准短情报数组 (Tavily)
  else if (json.intel && Array.isArray(json.intel)) {
    json.intel.forEach(i => addIntel(i));
  }
}

// 5. 组装最终的单一输出载荷给 Triage Agent
return {
  json: {
    content_id: content_id,
    topic_intent: topic_intent,
    triage_prompt: triage_prompt,
    target_count: target_count,
    valid_intel_count: allIntel.length,
    intel: allIntel
  }
};

// 1. 智能提取所有文本片段 (穿透 Grounding 嵌套)
let rawText = "";

if ($json.content && Array.isArray($json.content.parts)) {
  // 当开启了 Google Search 工具时，Gemini 会返回多个 parts
  // 我们过滤出所有包含 'text' 属性的 part，并把它们无缝拼接起来
  rawText = $json.content.parts
    .filter(part => part.text !== undefined)
    .map(part => part.text)
    .join("\n");
} else if ($json.text) {
  rawText = $json.text; // 兼容未触发工具时的常规结构
} else {
  rawText = JSON.stringify($json);
}

// 2. 暴力清洗与 JSON 解析 (防大模型幻觉)
let parsedData = {};
try {
  // 大模型有时会在 JSON 前后加废话，利用正则提取最外层的 {}
  const jsonMatch = rawText.match(/\{[\s\S]*\}/);
  let cleanText = jsonMatch ? jsonMatch[0] : rawText;

  // 彻底剔除 Markdown 代码块标记
  cleanText = cleanText.replace(/```json/gi, '').replace(/```/g, '').trim();

  parsedData = JSON.parse(cleanText);
} catch (error) {
  console.log("JSON 解析失败，原始文本:", rawText);
  // 终极底线：哪怕解析彻底崩溃，也要把几万字的长文保住，绝不丢失资产！
  parsedData = {
    content_id: "PARSE_ERROR",
    report_title: "解析异常_请人工核对",
    report_markdown: "## 网关解析异常\n未能成功解析大模型输出的 JSON，以下为原始返回文本：\n\n" + rawText
  };
}

// 3. 提取最终落盘字段
const content_id = parsedData.content_id || "MISSING_ID";
const title = parsedData.report_title || `Deep_Research_${content_id}`;
const markdown = parsedData.report_markdown || "# No content generated.";

// 4. 组装给 Google Drive 和 Database 的标准载荷
return {
  json: {
    content_id: content_id,
    file_name: `${title}.md`,
    file_content: markdown
  }
};

// 1. 获取当前节点 (DB Update) 的所有输入
const items = $input.all();

// 2. 跨节点安全获取持久化前的数据 (防弹寻址)
// 假设这批任务有多个，我们按索引或原样提取
const driveItems = $('Google Drive Upload').all();
const prepItems = $('Prepare Persistence Data').all();

// 3. 组装标准化的出口数据契约 (Return Payload)
return items.map((item, index) => {
  const prepData = prepItems[index]?.json || {};
  const driveData = driveItems[index]?.json || {};

  return {
    json: {
      content_id: prepData.content_id || item.json.content_id || "UNKNOWN_ID",
      status: "research_done",
      service_node: "[Atomic] Microscope_Gateway",
      drive_file_id: driveData.id || "MISSING_FILE_ID",
      file_name: prepData.file_name || "report.md",
      // 提取前 150 个字符作为摘要，方便母工作流进行飞书/钉钉/Slack 消息推送
      report_preview: prepData.file_content ? prepData.file_content.substring(0, 150).replace(/\n/g, ' ') + "..." : ""
    }
  };
});

// 获取 Apify 吐出的每一个 Item
const items = $input.all();

return items.map(item => {
  const data = item.json;

  // 1. 核心数据：提取 Apify 清洗好的 Markdown
  // 即使 Apify 有时会返回空，我们也要确保返回一个合法的 JSON 结构给下游
  const markdown = data.markdown || data.text || "# No content extracted";

  // 2. 来源数据：从原始输入中继承 content_id (这需要你在前序节点中透传)
  // 确保之前的节点把 content_id 挂载在 item.json 下
  const content_id = item.json.content_id || "MISSING_ID";
  const target_url = data.url || "";

  // 3. 返回标准化格式，直接对接 Aggregate Intel (Fan-in)
  return {
    json: {
      content_id: content_id,      // 身份牌：确保数据流不乱
      target_url: target_url,      // 溯源：标记这是哪个网页的数据
      markdown: markdown,          // 载荷：纯净的长文内容
      source: "Apify Crawler"      // 来源标签
    }
  };
});

// 1. 获取所有潜在搜索节点的引用
// 注意：请确保你的节点名称分别为 "Tavily Key A", "Tavily Key B", "Brave Search"
let nodeA, nodeB, nodeBrave;
try { nodeA = $("Tavily Key A").all(); } catch (e) {}
try { nodeB = $("Tavily Key B").all(); } catch (e) {}
try { nodeBrave = $("Brave Search").all(); } catch (e) {}

let rawResults = [];
let aiAnswer = "";
let sourceName = "";
let searchTopic = "";

// 2. 优先级判定：谁有数据就用谁 (A -> B -> Brave)
if (nodeA && nodeA[0]?.json?.results) {
  rawResults = nodeA[0].json.results;
  aiAnswer = nodeA[0].json.answer || "";
  sourceName = "Tavily (Key A)";
  searchTopic = nodeA[0].json.query || "";
} else if (nodeB && nodeB[0]?.json?.results) {
  rawResults = nodeB[0].json.results;
  aiAnswer = nodeB[0].json.answer || "";
  sourceName = "Tavily (Key B)";
  searchTopic = nodeB[0].json.query || "";
} else if (nodeBrave && nodeBrave[0]?.json?.web?.results) {
  // Brave 的字段映射：title, url, description -> content
  rawResults = nodeBrave[0].json.web.results.map(r => ({
    title: r.title,
    url: r.url,
    content: r.description
  }));
  sourceName = "Brave Search";
  searchTopic = $("Normalize Inputs").first().json.topic_intent || "";
}

// 3. 映射为全域标准情报格式 (符合你原本 Adapter 的 intel 契约)
let intel = rawResults.map(item => ({
  source: sourceName,
  title: item.title,
  url: item.url,
  snippet: item.content || ""
}));

// 4. 处理 Tavily 特有的 AI Answer (如果是从 Tavily 回来的话)
if (aiAnswer) {
  intel.unshift({
    source: sourceName + " Summary",
    title: "智能综述: " + searchTopic,
    url: "https://tavily.com",
    snippet: aiAnswer
  });
}

// 5. 极端兜底：如果三路全灭，给下游一个报错标记，防止 Aggregate 节点因空数据崩溃
if (intel.length === 0) {
  intel.push({
    source: "System Error",
    title: "⚠️ 搜索通道全线告急",
    url: "",
    snippet: "Tavily (A/B) 及 Brave Search 均未返回结果，请检查 API 额度或网络环境。"
  });
}

// 6. 最终输出给下游 Aggregate 节点
return { json: { intel: intel } };

